package com.ianblk.zianmobs;
import java.util.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.core.BlockPos;
/** Visual checks confined to an explicitly named development world. */
public final class CompanionScene {
 public static final int STAGES=40;
 private static final List<CompanionEntity> pets=new ArrayList<>();private static ServerPlayer viewer;private static Snowbone snow;private static double floor=-60;
 private static void guard(MinecraftServer server){if(!Boolean.getBoolean("zianmobs.scene")||!server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).toAbsolutePath().normalize().toString().contains("mobs-scene-client"))throw new IllegalStateException("Refusing scene outside isolated profile");}
 public static void setup(MinecraftServer server){guard(server);viewer=server.getPlayerList().getPlayers().getFirst();var level=server.overworld();floor=level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,48,48);server.setDifficulty(net.minecraft.world.Difficulty.NORMAL,true);level.setDayTime(6000);level.setWeatherParameters(100000,0,false,false);level.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,server);for(int x=33;x<=98;x++)for(int z=28;z<=69;z++){level.setBlockAndUpdate(BlockPos.containing(x,floor-1,z),Blocks.SMOOTH_STONE.defaultBlockState());for(int y=0;y<6;y++)level.setBlockAndUpdate(BlockPos.containing(x,floor+y,z),Blocks.AIR.defaultBlockState());}
  for(var entity:level.getEntitiesOfClass(LivingEntity.class,new net.minecraft.world.phys.AABB(33,floor-5,28,99,floor+10,70)))if(entity instanceof CompanionEntity||entity instanceof Snowbone)entity.discard();
  for(int i=0;i<CompanionContent.IDS.size();i++){String id=CompanionContent.IDS.get(i);var pet=CompanionContent.PETS.get(id).get().create(level);pet.moveTo(40+6*(i%8),floor,44+6*(i/8),180,0);pet.setYBodyRot(180);pet.setYHeadRot(180);pet.managed=true;pet.ownerId=UUID.randomUUID();pet.setNoAi(true);level.addFreshEntity(pet);pets.add(pet);}
  snow=Mobs.SNOWBONE.get().create(level);snow.moveTo(92,floor,44,180,0);snow.setYBodyRot(180);snow.setYHeadRot(180);snow.setNoAi(true);level.addFreshEntity(snow);viewer.setGameMode(GameType.SPECTATOR);stage(server,0);
 }
 public static void stage(MinecraftServer server,int stage){guard(server);if(stage==0)viewer.teleportTo(server.overworld(),61,floor+13,25,0,30);else if(stage<=29){var pet=pets.get(stage-1);viewer.teleportTo(server.overworld(),pet.getX(),floor-.6,pet.getZ()-3.4,0,8);}else if(stage<=31){viewer.teleportTo(server.overworld(),92,floor+.3,40,0,5);if(stage==31)snow.triggerAnim("main","shoot");}else if(stage==32){for(var pet:pets)pet.triggerAnim("main","scene_walk");viewer.teleportTo(server.overworld(),61,floor+13,25,0,30);}else if(stage==33){viewer.setGameMode(GameType.SURVIVAL);viewer.teleportTo(server.overworld(),55,floor,33,0,0);viewer.setHealth(8);Companions.current.grant(viewer.getUUID(),"gift",Long.MAX_VALUE);Companions.current.summon(viewer,"gift");Companions.current.support(Companions.current.activeEntity(viewer.getUUID()),viewer);}else if(stage==34){var pet=Companions.current.activeEntity(viewer.getUUID());if(pet==null||Companions.current.lastSupportNotice.isBlank())throw new IllegalStateException("Live support or chat notification failed");pet.moveTo(viewer.getX()+33,viewer.getY(),viewer.getZ());}else if(stage==35){if(Companions.current.activeEntity(viewer.getUUID())!=null)throw new IllegalStateException("Distant live companion did not store immediately");Companions.current.grant(viewer.getUUID(),"gift",0);if(Companions.current.allowed(viewer,"gift"))throw new IllegalStateException("Local revocation failed");}else if(stage>=36){viewer.setGameMode(GameType.SURVIVAL);viewer.teleportTo(server.overworld(),55,floor,33,0,10);viewer.stopUsingItem();viewer.setItemSlot(EquipmentSlot.MAINHAND,(stage==36||stage==38)?CompanionContent.EXTRAS.get("titan_double_sword").get().getDefaultInstance():net.minecraft.world.item.ItemStack.EMPTY);viewer.setItemSlot(EquipmentSlot.OFFHAND,stage>=37?CompanionContent.EXTRAS.get("titan_gauntlet").get().getDefaultInstance():net.minecraft.world.item.ItemStack.EMPTY);if(stage>=37)server.overworld().setDayTime(18000);if(stage==38){var victim=EntityType.COW.create(server.overworld());victim.moveTo(viewer.getX()+2,floor,viewer.getZ(),0,0);victim.setNoAi(true);server.overworld().addFreshEntity(victim);victim.hurt(viewer.damageSources().playerAttack(viewer),1000);victim.discard();if(!TitanAbilities.awakened(viewer))throw new IllegalStateException("Titan set did not activate on real kill");viewer.startUsingItem(net.minecraft.world.InteractionHand.OFF_HAND);}if(stage==39)viewer.removeAllEffects();}}
}
